For Shannon entropy,
\begin{align*}
\mathcal{H}^S(v)=\frac{1}{2}\ln(2\pi ev),\qquad
f^S(v)=\frac{v}{2},\qquad
p^\xi(v)=\frac{2\kappa}{v}. \refstepcounter{equation}\tag{\theequation}\label{shannon_entropy_specification}
\end{align*}
Thus, in the Shannon benchmark, auxiliary precision is inversely proportional to $v$.

For the Tsallis entropy with $\rho>1$,\footnote{Generalized models of rational inattention likewise use alternative entropy-based costs, including Tsallis entropy, to capture different information-processing frictions \citep{caplin2022rationally}.}
\begin{align*}
\mathcal{H}^{\rho}(v)&=\frac{1}{\rho-1}\left[1-\rho^{-1/2}(2\pi v)^{(1-\rho)/2}\right],\\
f^{\rho}(v)&=\frac{1}{2}\rho^{-1/2}(2\pi)^{(1-\rho)/2}v^{(3-\rho)/2},\\
p^\xi(v)&=2\kappa\rho^{1/2}(2\pi)^{(\rho-1)/2}v^{(\rho-3)/2}. \refstepcounter{equation}\tag{\theequation}\label{tsallis_entropy_specification}
\end{align*}
The Shannon specification is recovered as $\rho\to1$. Economically, $\rho$ determines how a fixed attention capacity translates into the precision of the auxiliary signal as posterior uncertainty changes: under full capacity, $p^\xi(v)$ increases as $v$ decreases for $1<\rho<3$, is independent of $v$ for $\rho=3$, and increases with $v$ for $\rho>3$. 
Both specifications satisfy \eqref{entropy_regular}.

\label{def_strategies}
Let $I\in\{AI,PO,NI\}$ and $(t,x,m,v)\in[0,T]\times\mathcal{O}$ be given. A trading strategy $\pi$ is admissible for investor $I$, and we write $\pi\in\mathcal{A}^I(t,x,m,v)$, if $\pi$ is $\mathbb{F}^I$-adapted and satisfies
\begin{align*}
\mathbb{E}^I_{t,x,m,v}\left[\int_t^T\pi_s^2ds\right]<\infty. \refstepcounter{equation}\tag{\theequation}\label{admissible_square_integrability}
\end{align*}
For $I\in\{AI,PO\}$, we additionally require the following family of random variables to be uniformly integrable:
\begin{align*}
\left\{\exp\left(-\gamma e^{r(T-\tau)}X_\tau^{\pi,I}\right):
\tau\text{ is an }\mathbb{F}^I\text{-stopping time in }[t,T]\right\}
\refstepcounter{equation}\tag{\theequation}\label{admissible_class_D}
\end{align*}

\label{proposition_31}
 Let $(t,x,m,v)\in[0,T)\times\mathcal{O}$ and $\kappa\in[0,\infty)$ be fixed. Then the attentive investor's optimal trading strategy is given by
\begin{align*}
\pi_s^{\ast,AI}=e^{-r(T-s)}\frac{m_s^{AI}-r}{\gamma\sigma^2}\frac{\sigma^2}{\sigma^2+(T-s)v_s^{AI}},\qquad s\in[t,T]. \refstepcounter{equation}\tag{\theequation}\label{optimal_strategy}
\end{align*}
Moreover, the corresponding value function is given by
\begin{align*}
V^{AI}(t,x,m,v;\kappa)=-\frac{1}{\gamma}\exp\left(-\gamma e^{r\left( T-t \right)}x-a(t,v)(m-r)^2-b^{AI}(t,v;\kappa)\right), \refstepcounter{equation}\tag{\theequation}\label{value_function}
\end{align*}
where
\begin{align*}
a(t,v)&=\frac{T-t}{2\left( \sigma^2+(T-t)v\right)}, \refstepcounter{equation}\tag{\theequation}\label{a_explicit}\\
b^{AI}(t,v;\kappa)&=\int_t^T
\left(\frac{(v_s^{AI})^2}{\sigma^2}
+\frac{\kappa(v_s^{AI})^2}{f(v_s^{AI})}\right)
a(s,v_s^{AI})ds. \refstepcounter{equation}\tag{\theequation}\label{b_integral}
\end{align*}

\label{propo_33}
Let $(t,x,m,v)\in[0,T)\times\mathcal{O}$ be fixed. Then the price observer's optimal trading strategy is given by
\begin{align*}
\pi_s^{\ast,PO}=e^{-r(T-s)}\frac{m_s^{PO}-r}{\gamma\sigma^2}\frac{\sigma^2}{\sigma^2+(T-s)v_s^{PO}}, \qquad s\in[t,T]. \refstepcounter{equation}\tag{\theequation}\label{strategy_price_observer}
\end{align*}
The corresponding value function is given by
\begin{align*}
V^{PO}(t,x,m,v)&=-\frac{1}{\gamma}\exp\left(-\gamma e^{r(T-t)}x-a(t,v)(m-r)^2-b^{PO}(t,v)\right), \refstepcounter{equation}\tag{\theequation}\label{value_function_price_observer}
\end{align*}
where $a(t,v)$ is given by \eqref{a_explicit}, and
\begin{align*}
b^{PO}(t,v)=\frac{1}{2}\ln\left( 1+\frac{(T-t)v}{\sigma^2}\right)-\frac{(T-t)v}{2(\sigma^2+(T-t)v)}>0. \refstepcounter{equation}\tag{\theequation}\label{b_po_explicit}
\end{align*}

\label{propo_34}
Let $(t,x,m,v)\in[0,T)\times\mathcal{O}$ be fixed. Then the naive investor's optimal deterministic trading strategy is given by  
\begin{align*}
\pi_s^{\ast,NI}=e^{-r(T-s)}\frac{m-r}{\gamma\sigma^2}\frac{\sigma^2}{\sigma^2+(T-t)v}, \qquad s\in\left[ t,T\right]. \refstepcounter{equation}\tag{\theequation}\label{strategy_naive_investor}
\end{align*}
The corresponding value function is given by
\begin{align*}
V^{NI}(t,x,m,v)=-\frac{1}{\gamma}\exp\left(-\gamma e^{r(T-t)}x-a(t,v)(m-r)^2\right), \refstepcounter{equation}\tag{\theequation}\label{value_function_naive_investor}
\end{align*}
where $a(t,v)$ is given by \eqref{a_explicit}.

\label{propo_35}
Let $(t,x,m,v)\in[0,T)\times\mathcal{O}$ be fixed. The perfect-learning limit of the attentive investor satisfies
\begin{align*}
V^{AI,\infty}(t,x,m,v):=\lim_{\kappa\to\infty}V^{AI}(t,x,m,v;\kappa)=\mathbb{E}_{m,v}\left[ V^{FI}(t,x;\mu)\right], \refstepcounter{equation}\tag{\theequation}\label{value_function_ai_infty}
\end{align*}
where $\mathbb{E}_{m,v}$ denotes expectation with respect to the current belief
$\mu\sim\mathcal{N}(m,v)$. Moreover,
\begin{align*}
V^{AI,\infty}(t,x,m,v)=-\frac{1}{\gamma}\exp\left(-\gamma e^{r(T-t)}x-a(t,v)(m-r)^2-b^{AI,\infty}(t,v)\right), \refstepcounter{equation}\tag{\theequation}\label{value_function_ai_infty_explicit}
\end{align*}
where $a(t,v)$ is given by \eqref{a_explicit} and
\begin{align*}
b^{AI,\infty}(t,v)&=\frac{1}{2}\ln\left( 1+\frac{(T-t)v}{\sigma^2}\right). \refstepcounter{equation}\tag{\theequation}\label{b_ai_infty}
\end{align*}
The corresponding limiting trading strategy is given, for $s\in(t,T]$, by
\begin{align*}
\pi_s^{\ast,AI,\infty}=e^{-r(T-s)}\frac{\mu-r}{\gamma\sigma^2}.
\refstepcounter{equation}\tag{\theequation}\label{strategy_ai_infty}
\end{align*}

\label{propo_41}
Let $(t,x,m,v)\in[0,T)\times\mathcal{O}$ and
$\kappa\in[0,\infty)$ be fixed. Then
\begin{align*}
P^{PO}_{EA}
&=\frac{e^{-r(T-t)}}{\gamma}b^{PO}(t,v),
\refstepcounter{equation}\tag{\theequation}\label{ex_ante_observation_value_explicit}\\
P^{AI}_{EA}(\kappa)
&=\frac{e^{-r(T-t)}}{\gamma}b^{AI}(t,v;\kappa),
\refstepcounter{equation}\tag{\theequation}\label{ex_ante_attention_value_explicit}\\
P^{AI}_{EA}(\kappa)-P^{PO}_{EA}
&=\frac{e^{-r(T-t)}}{\gamma}
\left( b^{AI}(t,v;\kappa)-b^{PO}(t,v)\right).
\refstepcounter{equation}\tag{\theequation}\label{ex_ante_incremental_attention_value_explicit}
\end{align*}
Moreover,
\begin{align*}
0<P^{PO}_{EA}=P^{AI}_{EA}(0)<P^{AI}_{EA}(\kappa),
\qquad \kappa>0,
\end{align*}
and $\kappa\mapsto P^{AI}_{EA}(\kappa)$ is strictly increasing.

\label{theorem_42}
Let $(t,x,m,v)\in[0,T)\times\mathcal{O}$, $\mu\in\mathbb{R}$, and $\kappa\in[0,\infty)$ be fixed. Set
\begin{align*} \lambda_s^\kappa:=q_s^{AI}v_s^{AI}\left(\frac{1}{\sigma^2}+\frac{\kappa}{f(v_s^{AI})}\right),\qquad q_s^{AI}&:=\frac{\sigma^2}{\sigma^2+(T-s)v_s^{AI}}, \qquad s\in[t,T]. \refstepcounter{equation}\tag{\theequation}\label{q_ai}
\end{align*}
Let $B(s;\kappa)$ and $C(s;\kappa)$ be the solutions of the terminal-value ODE system
\begin{align*}
\frac{d}{ds}B(s;\kappa)&=-2\lambda_s^\kappa\left( a(s,0)-B(s;\kappa)\right)+2q_s^{AI}v_s^{AI}\lambda_s^\kappa\left( a(s,0)-B(s;\kappa)\right)^2,\qquad B(T;\kappa)=0,\\
\frac{d}{ds}C(s;\kappa)&=-q_s^{AI}v_s^{AI}\lambda_s^\kappa\left( a(s,0)-B(s;\kappa)\right),\qquad C(T;\kappa)=0. \refstepcounter{equation}\tag{\theequation}\label{ode_system_correction_fluctuation}
\end{align*}
Then $B(t;\kappa)\in(0,a(t,0))$, $C(t;\kappa)\in(0,\frac{1}{2})$, and the scenario-conditional total value of attention satisfies
\begin{align*}
P^{AI}_{SC}(\mu,\kappa)=\frac{e^{-r(T-t)}}{\gamma}\left[\underbrace{B(t;\kappa)\left(\Delta^{NI}\right)^2}_{\text{correction benefit}}-\underbrace{C(t;\kappa)}_{\text{fluctuation cost}}\right]. \refstepcounter{equation}\tag{\theequation}\label{correction_fluctuation_decomposition}
\end{align*}
Consequently,
\begin{align*}
P^{AI}_{SC}(\mu,\kappa)\gtreqqless0\Longleftrightarrow B(t;\kappa)\left(\Delta^{NI}\right)^2\gtreqqless C(t;\kappa). \refstepcounter{equation}\tag{\theequation}\label{general_scenario_performance_condition}
\end{align*}

\label{propo_43}
Let $(t,x,m,v)\in[0,T)\times\mathcal{O}$ and $\kappa\in[0,\infty)$ be fixed. Then
\begin{align*}
P_{SC}^{AI}(\mu,\kappa)\overset{d}{=}\frac{e^{-r(T-t)}}{\gamma}\left[B(t;\kappa)Z_t^2-C(t;\kappa)\right],
\refstepcounter{equation}\tag{\theequation}\label{scenario_value_distribution}
\end{align*}
where
\begin{align*}
Z_t\sim\mathcal{N}\left(-\left(1-q_t^{NI}\right)(m-r),v\right).
\end{align*}
In particular,
\begin{align*}
\mathbb{E}_{m,v}\left[P_{SC}^{AI}(\mu,\kappa)\right]&=\frac{e^{-r(T-t)}}{\gamma}\left[B(t;\kappa)\left(v+\left(1-q_t^{NI}\right)^2(m-r)^2\right)-C(t;\kappa)\right],\\
\operatorname{Var}_{m,v}\left(P_{SC}^{AI}(\mu,\kappa)\right)&=\frac{e^{-2r(T-t)}}{\gamma^2}B(t;\kappa)^2\left[2v^2+4v\left(1-q_t^{NI}\right)^2(m-r)^2\right]. \refstepcounter{equation}\tag{\theequation}\label{mean_variance_p_sc}
\end{align*}

\label{propo_46}
Let $(x,m,v)\in\mathcal{O}$, $\mu\in\mathbb{R}$, and $\kappa>0$ be fixed, and let $\tau:=T-t$ denote the remaining horizon. The following second-order scaled limits hold:
\begin{align*}
\lim_{\tau\downarrow0}\frac{P^{PO}_{SC}(\mu;\tau)}{\tau^2}&=-\frac{v}{4\gamma\sigma^4}\left( v-2(m-\mu)^2\right), \refstepcounter{equation}\tag{\theequation}\label{short_horizon_po}\\
\lim_{\tau\downarrow0}\frac{P^{AI}_{SC}(\mu,\kappa;\tau)-P^{PO}_{SC}(\mu;\tau)}{\tau^2}&=-\frac{\kappa v}{4\gamma\sigma^2f(v)}\left( v-2(m-\mu)^2\right). \refstepcounter{equation}\tag{\theequation}\label{short_horizon_ai}
\end{align*}
Consequently, if $(m-\mu)^2<\frac{v}{2}$, then there exists $\varepsilon>0$ such that, for every $\tau\in(0,\varepsilon)$,
\begin{align*}
P^{AI}_{SC}(\mu,\kappa;\tau)<P^{PO}_{SC}(\mu;\tau)<0,
\end{align*}
where the arguments $\tau$ indicate the corresponding problem with terminal date $t+\tau$.

\label{propo_high_capacity_rates}
Let $(t,x,m,v)\in[0,T)\times\mathcal{O}$, $\bar\kappa\geq0$, and $\rho\geq1$ be fixed. There exist constants $0<K_1\leq K_2<\infty$ and $\kappa_0>\bar\kappa$, independent of $\kappa$ and $\mu$, such that every $\kappa\geq\kappa_0$ satisfies
\begin{align*}
K_1r_\rho(\kappa)
\leq
\sup_{\mu\in\mathbb{R}}
\frac{
P_{SC}^{AI,\infty}(\mu)-P_{SC}^{AI}(\mu,\kappa)
}{
P_{SC}^{AI,\infty}(\mu)-P_{SC}^{AI}(\mu,\bar\kappa)
}
\leq
K_2r_\rho(\kappa).
\refstepcounter{equation}\tag{\theequation}\label{voi_high_capacity_rates}
\end{align*}
Since $r_\rho(\kappa)\to0$, there exists $\widehat\kappa(\bar\kappa)>\bar\kappa$, independent of $\mu$, such that
\begin{align*}
P_{SC}^{AI}(\mu,\kappa)
>
P_{SC}^{AI}(\mu,\bar\kappa),
\qquad
\mu\in\mathbb{R},
\qquad
\kappa\geq\widehat\kappa(\bar\kappa).
\refstepcounter{equation}\tag{\theequation}\label{eventual_capacity_dominance}
\end{align*}
In particular, $\bar\kappa=0$ gives uniform eventual dominance over price observation.

\label{lemma_a1}
Let $(t,x,m,v)\in[0,T)\times\mathcal{O}$ be fixed. Then
\begin{align*}
\lim_{\kappa\to\infty}B(t;\kappa)=a(t,0), \qquad\lim_{\kappa\to\infty}C(t;\kappa)=0.
\end{align*}

Write $v_s^\kappa:=v_s^{\mathrm{AI}}$ and $q_s^\kappa:=q_s^{\mathrm{AI}}$, and define
\begin{align*}
A_\kappa&:=a(t,0)-B(t;\kappa),\\
E_\kappa&:=\frac{1}{2\sigma^2}\int_t^T q_s^\kappa v_s^\kappa ds,\\
w_0&:=q_t^{\mathrm{NI}}v>0.
\end{align*}
By \eqref{b_capacity_representation} and \eqref{b_ai_infty},
\begin{align*}
E_\kappa=b^{\mathrm{AI},\infty}(t,v)-b^{\mathrm{AI}}(t,v;\kappa).
\end{align*}
Moreover, \eqref{ex_ante_attention_value_aggreagated} and the identity
\begin{align*}
1+2vB(t;\kappa)=\left( 1+\frac{(T-t)v}{\sigma^2}\right)(1-2w_0A_\kappa)
\end{align*}
yield
\begin{align*}
E_\kappa=C(t;\kappa)-\frac{1}{2}\ln(1-2w_0A_\kappa).
\end{align*}
Since $0<A_\kappa<a(t,0)$ and $C(t;\kappa)>0$ by Theorem \ref{theorem_42}, we obtain
\begin{align*}
0<C(t;\kappa)&\le E_\kappa,\\
0<A_\kappa&\le\frac{1-e^{-2E_\kappa}}{2w_0} \le\frac{E_\kappa}{w_0}.
\end{align*}
By \eqref{variance_perfect_learning}, $v_s^\kappa\to0$ as $\kappa\to\infty$ for every $s>t$. Furthermore,
\begin{align*}
0<q_s^\kappa v_s^\kappa\le v, \qquad s\in[t,T].
\end{align*}
Dominated convergence therefore implies $E_\kappa\to0$. The preceding bounds give
\begin{align*}
A_\kappa\to0, \qquad C(t;\kappa)\to0,
\end{align*}
which proves both assertions.

\label{lemma_a3_aux}
Let $(t,x,m,v)\in[0,T)\times\mathcal{O}$, $\mu\in\mathbb{R}$, and $\kappa\in[0,\infty)$ be fixed. Let $\widetilde{\mathbb{P}}^{\mu}$ be the probability measure satisfying
\begin{align*}
\left.\frac{d\widetilde{\mathbb{P}}^{\mu}}{d\mathbb{P}^\mu}\right|_{\mathcal{F}^{AI}_T}
=\exp\left(-\int_t^T\frac{q_s^{AI}(m_s^{AI}-r)}{\sigma}dW_s^1-\frac{1}{2}\int_t^T\left(\frac{q_s^{AI}(m_s^{AI}-r)}{\sigma}\right)^2ds\right). \refstepcounter{equation}\tag{\theequation}\label{tilted_measure}
\end{align*}
Then the attentive investor's scenario-conditional expected utility satisfies
\begin{align*}
J^{AI}(t,x,m,v;\mu,\kappa)=V^{FI}(t,x;\mu)\widetilde{\mathbb{E}}^{\mu}_{t,x,m,v}\left[\exp\left(\frac{1}{2\sigma^2}\int_t^T\left(\Delta_s^{AI}\right)^2ds\right)\right], \refstepcounter{equation}\tag{\theequation}\label{j_ai_presentation}
\end{align*}
where 
\begin{align*}
    \Delta_s^{AI}&:=q_s^{AI}(m_s^{AI}-r)-(\mu-r), \qquad s\in[t,T]. \refstepcounter{equation}\tag{\theequation}\label{delta_ai}
\end{align*}

For fixed $\kappa$, set
\begin{align*}
h_s:=\frac{q_s^{AI}(m_s^{AI}-r)}{\sigma},
\qquad
\theta:=\frac{\mu-r}{\sigma}.
\end{align*}
Because $h$ is affine in the linear-Gaussian state with bounded deterministic coefficients, the Bene\v{s} linear-growth criterion \citep{klebaner2014stochastic} shows that the stochastic exponential in \eqref{tilted_measure} is a true martingale. Under $\widetilde{\mathbb{P}}^{\mu}$, completing the square gives
\begin{align*}
J^{AI}
={}&-\frac{1}{\gamma}e^{-\gamma e^{r(T-t)}x-\frac{1}{2}\theta^2(T-t)}
\widetilde{\mathbb{E}}^{\mu}_{t,x,m,v}
\left[\exp\left(\frac{1}{2}\int_t^T(h_s-\theta)^2ds\right)\right]\\
={}&V^{FI}(t,x;\mu)
\widetilde{\mathbb{E}}^{\mu}_{t,x,m,v}
\left[\exp\left(\frac{1}{2\sigma^2}
\int_t^T\left(\Delta_s^{AI}\right)^2ds\right)\right],
\end{align*}
which proves \eqref{j_ai_presentation}. It remains to verify finiteness of the exponential moment in \eqref{j_ai_presentation}. Under each $\mathbb{P}^{\vartheta}$, $m^{AI}$ is a Gaussian process whose covariance is independent of $\vartheta$. The parameter $\vartheta$ changes only its mean. Thus, by \eqref{scenario_conditional_wealth} and \eqref{optimal_strategy}, 
$\mathbb{E}^{\vartheta}_{t,x,m,v}[\exp(-\gamma X_T^{\pi^{*,AI}})]$
is a Gaussian quadratic exponential with a common quadratic kernel. Its prior average equals the finite Bayesian moment $-\gamma V^{AI}(t,x,m,v;\kappa)$, so it is finite for almost every $\vartheta$ under the prior. Since Gaussian quadratic integrability depends only on the common quadratic kernel, it is finite for every $\vartheta$, in particular for $\mu$. Hence $J^{AI}$, and therefore the exponential moment in
\eqref{j_ai_presentation}, is finite.

For use throughout the appendix, we define the total posterior-variance decay rate by
\begin{align*}
G_\kappa(y):=\frac{y^2}{\sigma^2}+\frac{\kappa y^2}{f(y)},\qquad y>0. \refstepcounter{equation}\tag{\theequation}\label{variance_decay_rate}
\end{align*}
Thus, the variance ODE in \eqref{filter_ai_compact} is
$dv_s^{AI}=-G_\kappa(v_s^{AI})ds$. Using
\eqref{wealth_learning_investor} and \eqref{filter_ai_compact}, define for a
smooth function $w=w(s,x,z,y)$ the second-order differential operator
\begin{align*}
\mathcal{L}^\pi w
:={}&\left( rx+\pi(z-r)\right) w_x-G_\kappa(y)w_y
+\frac{1}{2}\pi^2\sigma^2w_{xx}+\pi yw_{xz}
+\frac{1}{2}G_\kappa(y)w_{zz}.
\end{align*}
The dynamic programming principle for \eqref{portfolio_problem} leads to the HJB equation
\begin{align*}
0=W_s+\sup_{\pi\in\mathbb{R}}\mathcal{L}^\pi W,
\qquad W(T,x,z,y)=U(x). \refstepcounter{equation}\tag{\theequation}\label{hjb_equation}
\end{align*}




For each $(s,y)\in[0,T)\times\mathbb{R}_+$, let $(v_u)_{u\in[s,T]}$ be the
deterministic solution of
\begin{align*}
dv_u=-G_\kappa(v_u)du,\qquad v_s=y. \refstepcounter{equation}\tag{\theequation}\label{variance_characteristic}
\end{align*}
Condition \eqref{entropy_regular} implies that $G_\kappa(u)/u$ is bounded on
$(0,y]$, so comparison gives a unique strictly positive solution on $[s,T]$.
Since $G_\kappa\in C^1(0,\infty)$, the solution is continuously
differentiable in $(s,y)$. Define
\begin{align*}
a(s,y)&:=\frac{T-s}{2\left(\sigma^2+(T-s)y\right)}, \refstepcounter{equation}\tag{\theequation}\label{candidate_a}\\
b^{AI}(s,y;\kappa)&:=\int_s^T G_\kappa(v_u)a(u,v_u)du. \refstepcounter{equation}\tag{\theequation}\label{candidate_b}
\end{align*}
and consider
\begin{align*}
W(s,x,z,y):=-\frac{1}{\gamma}
\exp\left(-\gamma e^{r(T-s)}x-a(s,y)(z-r)^2-b^{AI}(s,y;\kappa)\right). \refstepcounter{equation}\tag{\theequation}\label{candidate_W}
\end{align*}
This function has the required interior regularity and satisfies the terminal
condition.

Since $W_{xx}<0$, its unique pointwise maximizer is
\begin{align*}
\pi^\ast(s,z,y)
&=-\frac{(z-r)W_x+yW_{xz}}{\sigma^2W_{xx}}\\
&=e^{-r(T-s)}\frac{z-r}{\gamma\sigma^2}
\left(1-2a(s,y)y\right)
=e^{-r(T-s)}\frac{z-r}{\gamma\sigma^2}
\frac{\sigma^2}{\sigma^2+(T-s)y}. \refstepcounter{equation}\tag{\theequation}\label{feedback_candidate}
\end{align*}
Direct differentiation of \eqref{candidate_a}--\eqref{candidate_b} along
\eqref{variance_characteristic} gives
\begin{align*}
a_s(s,y)-G_\kappa(y)a_y(s,y)
&=-\frac{1}{2\sigma^2}\left(1-2a(s,y)y\right)^2
+2G_\kappa(y)a(s,y)^2,\\
b_s^{AI}(s,y;\kappa)-G_\kappa(y)b_y^{AI}(s,y;\kappa)
&=-G_\kappa(y)a(s,y). \refstepcounter{equation}\tag{\theequation}\label{candidate_coefficient_equations}
\end{align*}
Both functions vanish at $s=T$, and substitution of
\eqref{candidate_coefficient_equations} verifies
\eqref{hjb_equation}. Evaluating \eqref{feedback_candidate} at
$(z,y)=(m_s^{AI},v_s^{AI})$ gives \eqref{optimal_strategy}.


Set
\begin{align*}
q_s:=\frac{\sigma^2}{\sigma^2+(T-s)v_s^{AI}}\in(0,1]. \refstepcounter{equation}\tag{\theequation}\label{candidate_attenuation}
\end{align*}
By It\^o's isometry and the variance ODE in \eqref{filter_ai_compact},
\begin{align*}
\mathbb{E}^{AI}_{t,x,m,v}\left[\left( m_s^{AI}-r\right)^2\right]
=(m-r)^2+\int_t^sG_\kappa(v_u^{AI})du
=(m-r)^2+v-v_s^{AI}. \refstepcounter{equation}\tag{\theequation}\label{posterior_second_moment}
\end{align*}
Thus, \eqref{feedback_candidate}, \eqref{candidate_attenuation}, and
\eqref{posterior_second_moment} show that the candidate trading strategy is predictable
and satisfies the square-integrability requirement
\eqref{admissible_square_integrability}:
\begin{align*}
\mathbb{E}^{AI}_{t,x,m,v}\left[\int_t^T|\pi_s^{\ast,AI}|^2ds\right]<\infty.
\end{align*}

To verify the class-$(D)$ condition, let
\begin{align*}
Y_s:=e^{r(T-s)}X_s^{\pi^{\ast,AI},AI},
\qquad \Xi_s^\ast:=e^{-\gamma Y_s}.
\end{align*}
The discounted-to-maturity wealth satisfies
\begin{align*}
Y_s
={}&e^{r(T-t)}x
+\frac{1}{\gamma\sigma^2}\int_t^sq_u\left( m_u^{AI}-r\right)^2du
+\frac{1}{\gamma\sigma}\int_t^sq_u\left( m_u^{AI}-r\right)
d\widehat W_u^{1,AI}. \refstepcounter{equation}\tag{\theequation}\label{candidate_wealth_to_maturity}
\end{align*}
Therefore, by \eqref{candidate_wealth_to_maturity},
\begin{align*}
\left( \Xi_s^\ast\right)^2
={}&\left( \Xi_t^\ast\right)^2
\mathcal{E}\left(-\frac{2}{\sigma}\int_t^\cdot
q_u\left( m_u^{AI}-r\right) d\widehat W_u^{1,AI}\right)_s\\
&\times\exp\left(-\frac{2}{\sigma^2}\int_t^s
q_u\left(1-q_u\right)\left( m_u^{AI}-r\right)^2du\right), \refstepcounter{equation}\tag{\theequation}\label{candidate_exponential_square}
\end{align*}
where $\mathcal{E}(\cdot)$ denotes the stochastic exponential. In \eqref{candidate_exponential_square}, the stochastic exponential is a
positive local martingale, hence a
supermartingale, while the second factor is at most one. Thus, for all
$\mathbb{F}^{AI}$-stopping times $\tau\in[t,T]$,
\begin{align*}
\sup_{\tau}\mathbb{E}^{AI}_{t,x,m,v}\left[\left( \Xi_\tau^\ast\right)^2\right]
\leq\left( \Xi_t^\ast\right)^2<\infty. \refstepcounter{equation}\tag{\theequation}\label{candidate_class_D_bound}
\end{align*}
By \eqref{candidate_class_D_bound}, the family $(\Xi_\tau^\ast)_\tau$ is
uniformly integrable, and
$\pi^{\ast,AI}\in\mathcal{A}^{AI}(t,x,m,v)$.


For an arbitrary admissible trading strategy $\pi$, the stochastic integral obtained by applying It\^o's formula to the candidate along the controlled state is initially only a local martingale. Let $(\tau_n)_{n\geq1}$ localize this integral. The HJB inequality then gives
\begin{align*}
\mathbb{E}^{AI}_{t,x,m,v}\left[
W\left(\tau_n,X_{\tau_n}^{\pi,AI},m_{\tau_n}^{AI},v_{\tau_n}^{AI}\right)\right]
\leq W(t,x,m,v). \refstepcounter{equation}\tag{\theequation}\label{localized_verification_inequality}
\end{align*}
Because $a,b^{AI}\geq0$,
\begin{align*}
\left|W\left( s,X_s^{\pi,AI},m_s^{AI},v_s^{AI}\right)\right|
\leq\frac{1}{\gamma}
\exp\left(-\gamma e^{r(T-s)}X_s^{\pi,AI}\right). \refstepcounter{equation}\tag{\theequation}\label{verification_domination}
\end{align*}
The class-$(D)$ condition \eqref{admissible_class_D}, together with \eqref{localized_verification_inequality}--\eqref{verification_domination}, permits passage to the limit $\tau_n\uparrow T$, yielding
\begin{align*}
\mathbb{E}^{AI}_{t,x,m,v}\left[ U\left( X_T^{\pi,AI}\right)\right]\leq W(t,x,m,v).
\end{align*}
For $\pi=\pi^{\ast,AI}$, the HJB drift is zero and \eqref{candidate_class_D_bound} gives the required class-$(D)$ property, hence equality. Therefore $W=V^{AI}$, and the unique HJB maximizer \eqref{feedback_candidate} is the optimal feedback trading strategy.

It is sufficient to prove the claim for $b^{AI}$. Write $v_s^\kappa$ for the variance path at capacity $\kappa$. If $0\leq\kappa_1<\kappa_2$, then $G_{\kappa_2}(y)>G_{\kappa_1}(y)$ for every $y>0$ because $f(y)>0$. Both paths start from $v$ and remain strictly positive by \eqref{entropy_regular}. The strict scalar ODE comparison theorem therefore
gives
\begin{align*}
v_s^{\kappa_2}<v_s^{\kappa_1},\qquad s\in(t,T]. \refstepcounter{equation}\tag{\theequation}\label{variance_capacity_order}
\end{align*}


We next rewrite $b^{AI}$ in a form that preserves this ordering. The variance
ODE in \eqref{filter_ai_compact} implies
\begin{align*}
d\ln\left(\sigma^2+(T-s)v_s^\kappa\right)
=-\frac{v_s^\kappa+(T-s)G_\kappa(v_s^\kappa)}
{\sigma^2+(T-s)v_s^\kappa}ds.
\end{align*}
Consequently, by \eqref{candidate_a},
\begin{align*}
G_\kappa(v_s^\kappa)a(s,v_s^\kappa)ds
={}&-\frac{1}{2}d\ln\left(\sigma^2+(T-s)v_s^\kappa\right)
-\frac{1}{2}\frac{v_s^\kappa}
{\sigma^2+(T-s)v_s^\kappa}ds.
\end{align*}
Since $v_t^\kappa=v$ and the logarithm has argument $\sigma^2$ at $s=T$,
integration and \eqref{b_integral} yield
\begin{align*}
b^{AI}(t,v;\kappa)
=\frac{1}{2}\ln\left(\frac{\sigma^2+(T-t)v}{\sigma^2}\right)
-\frac{1}{2}\int_t^T
\frac{v_s^\kappa}{\sigma^2+(T-s)v_s^\kappa}ds. \refstepcounter{equation}\tag{\theequation}\label{b_capacity_representation}
\end{align*}
For every $s\in[t,T]$,
\begin{align*}
\frac{\partial}{\partial y}\frac{y}{\sigma^2+(T-s)y}
=\frac{\sigma^2}{\left(\sigma^2+(T-s)y\right)^2}>0.
\end{align*}
Thus, \eqref{variance_capacity_order} and the strict monotonicity of
$y/(\sigma^2+(T-s)y)$ imply
\begin{align*}
\int_t^T\frac{v_s^{\kappa_2}}
{\sigma^2+(T-s)v_s^{\kappa_2}}ds
<\int_t^T\frac{v_s^{\kappa_1}}
{\sigma^2+(T-s)v_s^{\kappa_1}}ds.
\end{align*}
Together with \eqref{b_capacity_representation}, this gives
$b^{AI}(t,v;\kappa_2)>b^{AI}(t,v;\kappa_1)$. Finally,
\eqref{value_function} is strictly increasing in $b^{AI}$, which proves the
claim for $V^{AI}$.

By \eqref{investor_filtrations}, conditional on $\mathcal{G}_t$, every
$\mathbb{F}^{NI}$-predictable square-integrable trading strategy is a deterministic
element of $L^2([t,T])$. Define
\begin{align*}
k_s:=e^{r(T-s)}\pi_s.
\end{align*}
By the conditional-independence assumption following \eqref{prior_belief} and
the wealth equation \eqref{wealth_naive_investor}, terminal wealth is Gaussian
with mean and variance
\begin{align*}
\mathbb{E}^{NI}_{t,x,m,v}\left[ X_T^\pi\right]
&=e^{r(T-t)}x+(m-r)\int_t^Tk_sds,\\
\operatorname{Var}^{NI}_{t,x,m,v}\left( X_T^\pi\right)
&=v\left(\int_t^Tk_sds\right)^2+\sigma^2\int_t^Tk_s^2ds. \refstepcounter{equation}\tag{\theequation}\label{naive_terminal_moments}
\end{align*}
By the CARA utility \eqref{cara_utility}, the Gaussian moment-generating
function reduces the problem to
minimizing over $k\in L^2([t,T])$ the control-dependent exponent
\begin{align*}
{}&-\gamma(m-r)\int_t^Tk_sds
+\frac{\gamma^2v}{2}\left(\int_t^Tk_sds\right)^2
+\frac{\gamma^2\sigma^2}{2}\int_t^Tk_s^2ds. \refstepcounter{equation}\tag{\theequation}\label{naive_control_exponent}
\end{align*}
For a fixed value of $\int_t^Tk_sds$, the first two terms are fixed, while
Cauchy--Schwarz gives
\begin{align*}
\int_t^Tk_s^2ds\geq
\frac{1}{T-t}\left(\int_t^Tk_sds\right)^2,
\end{align*}
with equality if and only if $k$ is constant almost everywhere. Hence every
minimizer must satisfy $k_s^\ast=c$. Substitution reduces the problem to minimizing
the strictly convex scalar expression
\begin{align*}
(T-t)\left[-\gamma(m-r)c
+\frac{\gamma^2}{2}\left(\sigma^2+(T-t)v\right) c^2\right].
\end{align*}
Its first-order condition yields
\begin{align*}
c=\frac{m-r}{\gamma\left(\sigma^2+(T-t)v\right)},
\end{align*}
which is the unique global minimizer. Therefore,
\begin{align*}
\pi_s^{\ast,NI}
=e^{-r(T-s)}\frac{m-r}{\gamma\sigma^2}
\frac{\sigma^2}{\sigma^2+(T-t)v}.
\end{align*}
This is \eqref{strategy_naive_investor}.

The candidate satisfies \eqref{admissible_square_integrability} and is therefore
admissible. More generally, \eqref{naive_terminal_moments} shows that terminal
wealth is Gaussian under every $L^2$ trading strategy, so its terminal exponential
moment is finite. Finally, substituting the optimizer into
\eqref{naive_control_exponent} gives
\begin{align*}
{}&-\gamma(m-r)\int_t^Tk_s^\ast ds
+\frac{\gamma^2v}{2}\left(\int_t^Tk_s^\ast ds\right)^2
+\frac{\gamma^2\sigma^2}{2}\int_t^T\left( k_s^\ast\right)^2ds\\
&=-\frac{(T-t)(m-r)^2}{2\left(\sigma^2+(T-t)v\right)}
=-a(t,v)(m-r)^2,
\end{align*}
which gives \eqref{value_function_naive_investor}.

Write $v_s^\kappa:=v_s^{AI}$. Since $G_\kappa>0$, the variance path is
decreasing. For $\kappa>0$ and $s>t$, separation of the variance ODE in
\eqref{filter_ai_compact} gives
\begin{align*}
s-t
=\int_{v_s^\kappa}^v\frac{du}{G_\kappa(u)}
\leq\frac{1}{\kappa}\int_{v_s^\kappa}^v\frac{f(u)}{u^2}du.
\end{align*}
The inequality uses $G_\kappa(u)\geq\kappa u^2/f(u)$. Fix
$\varepsilon\in(0,v)$. If $v_s^\kappa\geq\varepsilon$, then
\begin{align*}
\kappa(s-t)\leq\int_\varepsilon^v\frac{f(u)}{u^2}du<\infty,
\end{align*}
which is impossible for all sufficiently large $\kappa$. Hence
\begin{align*}
v_s^\kappa\longrightarrow0,\qquad s\in(t,T]. \refstepcounter{equation}\tag{\theequation}\label{variance_perfect_learning}
\end{align*}

In \eqref{b_capacity_representation}, the integrand is bounded by
$v/\sigma^2$ and converges to zero for almost every $s$ by
\eqref{variance_perfect_learning}. Dominated convergence therefore yields
\begin{align*}
b^{AI}(t,v;\kappa)\longrightarrow
b^{AI,\infty}(t,v)
=\frac{1}{2}\ln\left(1+\frac{(T-t)v}{\sigma^2}\right). \refstepcounter{equation}\tag{\theequation}\label{b_perfect_limit}
\end{align*}
The limit agrees with \eqref{b_ai_infty}.
Substitution into \eqref{value_function} proves
\eqref{value_function_ai_infty_explicit}.

For completeness, the standard one-state CARA problem with known drift has the trading strategy and value stated in \eqref{full_information_strategy} and
\eqref{value_function_full_info}:
\begin{align*}
\pi_s^{\ast,FI}
&=e^{-r(T-s)}\frac{\mu-r}{\gamma\sigma^2},
\qquad s\in[t,T],\\
V^{FI}(t,x;\mu)
&=-\frac{1}{\gamma}\exp\left(-\gamma e^{r(T-t)}x
-\frac{T-t}{2\sigma^2}(\mu-r)^2\right).
\end{align*}
If $\mu\sim\mathcal{N}(m,v)$, Gaussian integration gives
\begin{align*}
\mathbb{E}_{m,v}\left[
e^{-\frac{T-t}{2\sigma^2}(\mu-r)^2}\right]
&=\frac{
\exp\left(-\frac{(T-t)(m-r)^2}
{2\left(\sigma^2+(T-t)v\right)}\right)}
{\sqrt{1+\frac{(T-t)v}{\sigma^2}}}\\
&=\exp\left(-a(t,v)(m-r)^2-b^{AI,\infty}(t,v)\right).
\end{align*}
The last equality follows from \eqref{a_explicit} and
\eqref{b_perfect_limit}. Multiplying by the wealth-dependent factor in
$V^{FI}$ gives
\begin{align*}
\mathbb{E}_{m,v}\left[ V^{FI}(t,x;\mu)\right]
&=-\frac{1}{\gamma}\exp\left(-\gamma e^{r(T-t)}x
-a(t,v)(m-r)^2-b^{AI,\infty}(t,v)\right)\\
&=V^{AI,\infty}(t,x,m,v).
\end{align*}

Finally, let
\begin{align*}
q_s^\kappa:=\frac{\sigma^2}{\sigma^2+(T-s)v_s^\kappa}.
\end{align*}
By \eqref{posterior_moments}, $m_s^{AI}=\mathbb{E}[\mu\mid\mathcal{F}_s^{AI}]$ and
$v_s^\kappa=\operatorname{Var}(\mu\mid\mathcal{F}_s^{AI})$ is deterministic. The tower
property gives
\begin{align*}
\mathbb{E}^{AI}_{t,x,m,v}\left[\left( m_s^{AI}-\mu\right)^2\right]
&=\mathbb{E}^{AI}_{t,x,m,v}\left[\operatorname{Var}\left(\mu\mid\mathcal{F}_s^{AI}\right)\right]
=v_s^\kappa. \refstepcounter{equation}\tag{\theequation}\label{posterior_mse_bayesian}
\end{align*}
Thus, by \eqref{variance_perfect_learning}--\eqref{posterior_mse_bayesian}, for
every $s>t$, $m_s^{AI}\to\mu$ in $L^2$ and
$q_s^\kappa\to1$. Moreover,
\begin{align*}
{}&\mathbb{E}^{AI}_{t,x,m,v}\left[
\left( q_s^\kappa(m_s^{AI}-r)-(\mu-r)\right)^2\right]\\
&\leq2v_s^\kappa
+2\left(1-q_s^\kappa\right)^2\left[(m-r)^2+v\right]. \refstepcounter{equation}\tag{\theequation}\label{strategy_error_bound}
\end{align*}
The right-hand side of \eqref{strategy_error_bound} converges to zero for every
$s>t$ and is bounded by
an integrable constant independent of $s$ and $\kappa$. Dominated convergence
therefore also gives convergence in $L^2(\mathbb{P}\otimes ds)$:
\begin{align*}
\pi_s^{\ast,AI}
\longrightarrow e^{-r(T-s)}\frac{\mu-r}{\gamma\sigma^2}.
\end{align*}
This proves \eqref{strategy_ai_infty}. The value assigned at time $s=t$ is immaterial.

Under $\widetilde{\mathbb{P}}^{\mu}$ defined by \eqref{tilted_measure},
Girsanov's theorem gives
\begin{align*}
dm_s^{AI}={}&-\left[\frac{G_\kappa(v_s^{AI})}{v_s^{AI}}\left(m_s^{AI}-\mu\right)+\frac{v_s^{AI}q_s^{AI}}{\sigma^2}\left(m_s^{AI}-r\right)\right]ds\\
&+\frac{v_s^{AI}}{\sigma}d\widetilde W_s^1+v_s^{AI}\sqrt{\frac{\kappa}{f(v_s^{AI})}}dW_s^2. \refstepcounter{equation}\tag{\theequation}\label{tilted_filter_dynamics}
\end{align*}
Using \eqref{q_ai} and \eqref{filter_ai_compact}, direct differentiation gives
\begin{align*}
\frac{d}{ds}q_s^{AI}=q_s^{AI}v_s^{AI}\left[\left(1-q_s^{AI}\right)\left(\frac{1}{\sigma^2}+\frac{\kappa}{f(v_s^{AI})}\right)+\frac{q_s^{AI}}{\sigma^2}\right].
\end{align*}
Hence, using the definition of $\Delta_s^{AI}$ in \eqref{delta_ai},
\begin{align*}
d\Delta_s^{AI}=-\lambda_s^\kappa\Delta_s^{AI}ds+\sqrt{q_s^{AI}v_s^{AI}\lambda_s^\kappa} d\widetilde W_s, \qquad \Delta_t^{AI}=\Delta^{NI}, \refstepcounter{equation}\tag{\theequation}\label{tilted_gap_dynamics}
\end{align*}
for a $\widetilde{\mathbb{P}}^{\mu}$-Brownian motion $\widetilde W$. Set
\begin{align*}
A(s;\kappa):=a(s,0)-B(s;\kappa).
\end{align*}
Since $d/ds a(s,0)=-1/(2\sigma^2)$, the ODEs in the theorem are
equivalent to
\begin{align*}
\frac{d}{ds} A(s;\kappa)&=2\lambda_s^\kappa A(s;\kappa)-2q_s^{AI}v_s^{AI}\lambda_s^\kappa A(s;\kappa)^2-\frac{1}{2\sigma^2}, \qquad A(T;\kappa)=0,\\
\frac{d}{ds} C(s;\kappa)&=-q_s^{AI}v_s^{AI}\lambda_s^\kappa A(s;\kappa), \qquad C(T;\kappa)=0. \refstepcounter{equation}\tag{\theequation}\label{AC_system}
\end{align*}
Moreover,
\begin{align*}
q_s^{AI}v_s^{AI}a(s,0)=\frac{q_s^{AI}v_s^{AI}(T-s)}{2\sigma^2}=\frac{1-q_s^{AI}}{2}<\frac{1}{2}.
\end{align*}
Backward scalar comparison in the first equation of \eqref{AC_system}, using $0$ and $a(s,0)$ as comparison functions, gives
\begin{align*}
0<A(s;\kappa)<a(s,0), \qquad s\in[t,T).
\end{align*}
Consequently,
\begin{align*}
0<B(s;\kappa)<a(s,0), \qquad C(s;\kappa)=\int_s^Tq_u^{AI}v_u^{AI}\lambda_u^\kappa A(u;\kappa)du>0. \refstepcounter{equation}\tag{\theequation}\label{BC_positive}
\end{align*}
Using the preceding expression for $d q_s^{AI}/ds$ and $A(s;\kappa)<a(s,0)$,
\begin{align*}
q_s^{AI}v_s^{AI}\lambda_s^\kappa A(s;\kappa)<\frac{1-q_s^{AI}}{2}\lambda_s^\kappa<\frac{1}{2}\frac{d}{ds}q_s^{AI}.
\end{align*}
Therefore,
\begin{align*}
0<C(t;\kappa)<\frac{1}{2}\int_t^T\frac{d}{ds}q_s^{AI}ds=\frac{1-q_t^{NI}}{2}<\frac{1}{2}.
\end{align*}
Now define
\begin{align*}
F(s,d)=\exp\left(A(s;\kappa)d^2+C(s;\kappa)\right).
\end{align*}
By \eqref{AC_system}, $F$ solves
\begin{align*}
F_s-\lambda_s^\kappa dF_d+\frac{1}{2}q_s^{AI}v_s^{AI}\lambda_s^\kappa F_{dd}+\frac{d^2}{2\sigma^2}F=0, \qquad F(T,d)=1.
\end{align*}
Applying the Feynman--Kac formula to
\eqref{tilted_gap_dynamics} yields
\begin{align*}
\widetilde{\mathbb{E}}_{t,x,m,v}^{\mu}\left[\exp\left(\frac{1}{2\sigma^2}\int_t^T\left(\Delta_s^{AI}\right)^2ds\right)\right]=\exp\left(\left(a(t,0)-B(t;\kappa)\right)\left(\Delta^{NI}\right)^2+C(t;\kappa)\right). \refstepcounter{equation}\tag{\theequation}\label{gap_moment_decomposition}
\end{align*}
The required exponential integrability follows from the argument in the
proof of Lemma \ref{lemma_a3_aux}. Combining
\eqref{gap_moment_decomposition} with \eqref{j_ai_presentation} and
\begin{align*}
J^{NI}(t,x,m,v;\mu)
=V^{FI}(t,x;\mu)\exp\left( a(t,0)\left(\Delta^{NI}\right)^2\right),
\end{align*}
and applying inverse utility, gives
\begin{align*}
P^{AI}_{SC}(\mu,\kappa)=\frac{e^{-r(T-t)}}{\gamma}\left[B(t;\kappa)\left(\Delta^{NI}\right)^2-C(t;\kappa)\right].
\end{align*}
Together with \eqref{BC_positive}, this proves the result.

By \eqref{prior_belief} and \eqref{trading_strategy_gaps},
\begin{align*}
\Delta^{NI}=q_t^{NI}(m-r)-(\mu-r)\sim\mathcal{N}\left(-\left(1-q_t^{NI}\right)(m-r),v\right).
\end{align*}
Hence, with $Z_t$ as in the proposition,
\begin{align*}
\left(\Delta^{NI}\right)^2\overset{d}{=}Z_t^2.
\end{align*}
Substitution into \eqref{correction_fluctuation_decomposition} yields
\begin{align*}
P_{SC}^{AI}(\mu,\kappa)\overset{d}{=}\frac{e^{-r(T-t)}}{\gamma}\left[B(t;\kappa)Z_t^2-C(t;\kappa)\right],
\end{align*}
as was to be shown.

For each $\tau>0$, take terminal date $t+\tau$ and define
\begin{align*}
K_\kappa(\tau)
:=2\sigma^2\ln\widetilde{\mathbb{E}}^{\mu}_{t,x,m,v}
\left[\exp\left(\frac{1}{2\sigma^2}\int_t^{t+\tau}
\left(\Delta_s^{AI}\right)^2ds\right)\right]. \refstepcounter{equation}\tag{\theequation}\label{short_horizon_K}
\end{align*}
Here the measure and processes on the right correspond to $\kappa$. By
\eqref{short_horizon_K}, \eqref{scenario_conditional_certainty_equivalents}, and
\eqref{j_ai_presentation},
\begin{align*}
CE^{AI}_{SC}(\mu;\tau)
=x+\frac{e^{-r\tau}}{2\gamma\sigma^2}
\left[\tau(\mu-r)^2-K_\kappa(\tau)\right]. \refstepcounter{equation}\tag{\theequation}\label{short_horizon_CE}
\end{align*}
Since $\kappa=0$ gives the price observer, \eqref{short_horizon_CE} yields
\begin{align*}
P^{AI}_{SC}(\mu,\kappa;\tau)-P^{PO}_{SC}(\mu;\tau)
=-\frac{e^{-r\tau}}{2\gamma\sigma^2}
\left( K_\kappa(\tau)-K_0(\tau)\right). \refstepcounter{equation}\tag{\theequation}\label{ce_short_horizon}
\end{align*}
After setting $s=t+\tau y$, the variance ODE in \eqref{filter_ai_compact} and
the affine Gaussian dynamics \eqref{tilted_filter_dynamics} imply, uniformly
for $y\in[0,1]$,
\begin{align*}
\frac{q_{t+\tau y}^{AI}-1}{\tau}
&\longrightarrow-\frac{(1-y)v}{\sigma^2},\\
\frac{\widetilde{\mathbb{E}}^{\mu}_{t,x,m,v}
\left[ m_{t+\tau y}^{AI}-m\right]}{\tau}
&\longrightarrow-y\left[\frac{G_\kappa(v)}{v}(m-\mu)
+\frac{v}{\sigma^2}(m-r)\right],\\
\frac{\widetilde{\mathbb{E}}^{\mu}_{t,x,m,v}
\left[\left( m_{t+\tau y}^{AI}-m\right)^2\right]}{\tau}
&\longrightarrow yG_\kappa(v). \refstepcounter{equation}\tag{\theequation}\label{short_horizon_filter_limits}
\end{align*}
Expanding the square in \eqref{delta_ai} and applying dominated
convergence to \eqref{short_horizon_filter_limits} give
\begin{align*}
&\lim_{\tau\downarrow0}\frac{1}{\tau^2}\Bigg\{
\widetilde{\mathbb{E}}^{\mu}_{t,x,m,v}
\left[\int_t^{t+\tau}\left(\Delta_s^{AI}\right)^2ds\right]
-\tau(m-\mu)^2\Bigg\}\\
&=-\frac{2v}{\sigma^2}(m-\mu)(m-r)
-\frac{G_\kappa(v)}{v}(m-\mu)^2+\frac{G_\kappa(v)}{2}. \refstepcounter{equation}\tag{\theequation}\label{integrated_gap_limit}
\end{align*}
Gaussian fourth-moment bounds and local exponential integrability also give
\begin{align*}
\lim_{\tau\downarrow0}\frac{1}{\tau^2}
\operatorname{Var}_{\widetilde{\mathbb{P}}^{\mu}}
\left(\int_t^{t+\tau}\left(\Delta_s^{AI}\right)^2ds\right)&=0,\\
\lim_{\tau\downarrow0}\frac{1}{\tau^2}\Bigg\{
K_\kappa(\tau)-\widetilde{\mathbb{E}}^{\mu}_{t,x,m,v}
\left[\int_t^{t+\tau}\left(\Delta_s^{AI}\right)^2ds\right]\Bigg\}&=0. \refstepcounter{equation}\tag{\theequation}\label{short_horizon_cumulant_control}
\end{align*}
Subtracting \eqref{integrated_gap_limit} at $\kappa=0$ and using
\eqref{variance_decay_rate} and \eqref{short_horizon_cumulant_control} yield
\begin{align*}
\lim_{\tau\downarrow0}\frac{K_\kappa(\tau)-K_0(\tau)}{\tau^2}
=\frac{\kappa v}{2f(v)}\left( v-2(m-\mu)^2\right). \refstepcounter{equation}\tag{\theequation}\label{short_horizon_K_difference}
\end{align*}
Together, \eqref{ce_short_horizon} and \eqref{short_horizon_K_difference} give
\begin{align*}
\lim_{\tau\downarrow0}\frac{P^{AI}_{SC}(\mu,\kappa;\tau)
-P^{PO}_{SC}(\mu;\tau)}{\tau^2}
=-\frac{\kappa v}{4\gamma\sigma^2f(v)}
\left( v-2(m-\mu)^2\right),
\end{align*}
which proves \eqref{short_horizon_ai}.

For the price observer, set
$q:=\frac{\sigma^2}{\sigma^2+\tau v}$ and write $C(q):=C(t;0)$. Then \eqref{correction_fluctuation_decomposition} and \eqref{b_c_po} give
\begin{align*}
P^{PO}_{SC}(\mu;\tau)
=\frac{e^{-r\tau}}{\gamma}
\left[\frac{(1-q)a(t,0)}{2-q}\left(\Delta^{NI}\right)^2-C(q)\right]. \refstepcounter{equation}\tag{\theequation}\label{price_observer_short_horizon_exact}
\end{align*}
The required elementary limits are
\begin{align*}
\lim_{\tau\downarrow0}\frac{1-q}{\tau}
&=\frac{v}{\sigma^2},&
\lim_{\tau\downarrow0}\Delta^{NI}&=m-\mu,&
\lim_{q\uparrow1}\frac{C(q)}{(1-q)^2}&=\frac{1}{4}. \refstepcounter{equation}\tag{\theequation}\label{price_observer_short_horizon_limits}
\end{align*}
Combining \eqref{price_observer_short_horizon_exact}--\eqref{price_observer_short_horizon_limits}
with $a(t,0)=\frac{\tau}{2\sigma^2}$ gives
\begin{align*}
\lim_{\tau\downarrow0}\frac{P^{PO}_{SC}(\mu;\tau)}{\tau^2}
=-\frac{v}{4\gamma\sigma^4}\left( v-2(m-\mu)^2\right),
\end{align*}
which proves \eqref{short_horizon_po}. If
$(m-\mu)^2<\frac{v}{2}$, both limits are strictly negative, so the asserted
ordering holds for all sufficiently small $\tau>0$.

For positive quantities depending on $\kappa$, write $x_\kappa\asymp y_\kappa$ when $x_\kappa/y_\kappa$ is bounded above and bounded away from zero for all sufficiently large $\kappa$. Comparisons involving $u$ are uniform over the stated range of $u$. All comparison constants may depend on the fixed state, benchmark, and model parameters but not on $\kappa$ or $\mu$.

Set $\tau:=T-t$, $u:=s-t\in[0,\tau]$, and suppress fixed initial arguments. The Shannon and Tsallis specifications can be written jointly as
\begin{align*}
f^\rho(y)=c_\rho y^{1-\beta_\rho},\qquad
\beta_\rho:=\frac{\rho-1}{2},\qquad
c_\rho:=\frac{1}{2}\rho^{-1/2}(2\pi)^{(1-\rho)/2},
\end{align*}
where $\rho=1$ gives the Shannon specification. Write $v_\kappa(u):=v_{t+u}^{AI}$ and $q_\kappa(u):=q_{t+u}^{AI}$. The variance equation becomes
\begin{align*}
\frac{d}{du}v_\kappa(u)
=-\frac{v_\kappa(u)^2}{\sigma^2}
-\frac{\kappa}{c_\rho}v_\kappa(u)^{1+\beta_\rho},
\qquad v_\kappa(0)=v.
\refstepcounter{equation}\tag{\theequation}\label{power_variance_ode}
\end{align*}
If $\beta_\rho=0$, scalar comparison gives
\begin{align*}
v_\kappa(u)\asymp\exp\left(-\frac{\kappa u}{c_\rho}\right),
\qquad u\in[0,\tau].
\end{align*}
If $\beta_\rho>0$, differentiating $v_\kappa^{-\beta_\rho}$ gives
\begin{align*}
\frac{d}{du}v_\kappa(u)^{-\beta_\rho}
=\frac{\beta_\rho\kappa}{c_\rho}
+\frac{\beta_\rho}{\sigma^2}v_\kappa(u)^{1-\beta_\rho}.
\end{align*}
The second term is bounded when $\beta_\rho\leq1$ and sublinear in $v_\kappa^{-\beta_\rho}$ when $\beta_\rho>1$. Scalar comparison on $[0,\tau]$ therefore yields
\begin{align*}
v_\kappa(u)\asymp(1+\kappa u)^{-\frac{1}{\beta_\rho}},
\qquad u\in[0,\tau].
\refstepcounter{equation}\tag{\theequation}\label{power_variance_comparison}
\end{align*}
All comparison constants may depend on $(\tau,v,\sigma,\rho)$ but not on $\kappa$ or $u$. Hence, for every $p>0$,
\begin{align*}
\int_0^\tau v_\kappa(u)^pdu
\asymp
\begin{cases}
\kappa^{-1},&\beta_\rho=0\text{ or }0<\beta_\rho<p,\\
\frac{\ln(1+\kappa)}{\kappa},&\beta_\rho=p,\\
\kappa^{-\frac{p}{\beta_\rho}},&\beta_\rho>p.
\end{cases}
\refstepcounter{equation}\tag{\theequation}\label{variance_integral_rates}
\end{align*}
As in the proof of Theorem \ref{theorem_42}, write $A(s;\kappa):=a(s,0)-B(s;\kappa)$, and set
\begin{align*}
w_\kappa(u):=q_\kappa(u)v_\kappa(u),\qquad
\lambda_\kappa(u):=\lambda_{t+u}^\kappa.
\end{align*}
Since $q_t^{NI}\leq q_\kappa(u)\leq1$, $w_\kappa(u)\asymp v_\kappa(u)$ uniformly. The first equation in \eqref{AC_system} and variation of constants give
\begin{align*}
A(t;\kappa)=\frac{1}{2\sigma^2}\int_0^\tau
\exp\left(-2\int_0^u\lambda_\kappa(y)\left[1-w_\kappa(y)A(t+y;\kappa)\right] dy\right) du.
\refstepcounter{equation}\tag{\theequation}\label{A_variation_constants}
\end{align*}
By \eqref{correction_fluctuation_decomposition} and \eqref{p_sc_limit},
\begin{align*}
P_{SC}^{AI,\infty}(\mu)-P_{SC}^{AI}(\mu,\kappa)
=
\frac{e^{-r(T-t)}}{\gamma}
\left[
A(t;\kappa)\left(\Delta^{NI}\right)^2+C(t;\kappa)
\right].
\end{align*}
By Lemma \ref{lemma_a1}, $C(t;\kappa)\to0$ as $\kappa\to\infty$. Moreover, \eqref{BC_positive} implies
\begin{align*}
0\leq\int_0^u w_\kappa(y)\lambda_\kappa(y)A(t+y;\kappa)dy\leq C(t;\kappa)\to0,
\qquad u\in[0,\tau].
\end{align*}
Hence, the nonlinear contribution to the exponent in \eqref{A_variation_constants} converges uniformly to zero. Direct differentiation of
\begin{align*}
\frac{1}{w_\kappa(u)}
=
\frac{1}{v_\kappa(u)}
+
\frac{\tau-u}{\sigma^2}
\end{align*}
and \eqref{power_variance_ode} gives
\begin{align*}
\frac{d}{du}w_\kappa(u)
&=-\frac{\kappa w_\kappa(u)^2}{f^\rho(v_\kappa(u))},\\
\lambda_\kappa(u)
&=\frac{w_\kappa(u)}{\sigma^2}
-\frac{d}{du}\ln w_\kappa(u).
\end{align*}
Consequently,
\begin{align*}
\exp\left(-2\int_0^u\lambda_\kappa(y)dy\right)
=
\left(\frac{w_\kappa(u)}{w_\kappa(0)}\right)^2
\exp\left(-\frac{2}{\sigma^2}\int_0^u w_\kappa(y)dy\right).
\end{align*}
The last exponential is bounded above and bounded away from zero uniformly. Since $w_\kappa(0)=q_t^{NI}v$ is independent of $\kappa$, it follows from \eqref{A_variation_constants} that
\begin{align*}
A(t;\kappa)\asymp\int_0^\tau v_\kappa(u)^2du.
\refstepcounter{equation}\tag{\theequation}\label{A_variance_integral}
\end{align*}

The identity established in the proof of Lemma \ref{lemma_a1} gives
\begin{align*}
\frac{1}{2\sigma^2}\int_0^\tau w_\kappa(u)du
=
C(t;\kappa)
-\frac{1}{2}\ln\left(1-2w_\kappa(0)A(t;\kappa)\right).
\refstepcounter{equation}\tag{\theequation}\label{C_variance_identity}
\end{align*}
The left-hand side has the order of $\int_0^\tau v_\kappa(u)du$, while the logarithmic term has the order of $A(t;\kappa)$. If $\beta_\rho\geq1$, \eqref{variance_integral_rates} and \eqref{A_variance_integral} show that $A(t;\kappa)$ has strictly smaller order than $\int_0^\tau v_\kappa(u)du$. Therefore,
\begin{align*}
C(t;\kappa)\asymp\int_0^\tau v_\kappa(u)du.
\end{align*}

If $0\leq\beta_\rho<1$, restrict the integral representation in \eqref{BC_positive} to
\begin{align*}
u\in\left[\frac{c_1}{\kappa},\frac{c_2}{\kappa}\right]
\end{align*}
for fixed $0<c_1<c_2$. On this interval, scalar comparison gives $w_\kappa(u)$ bounded away from zero, $\lambda_\kappa(u)\asymp\kappa$, and $A(t+u;\kappa)\asymp\kappa^{-1}$. This gives the matching lower bound, while \eqref{C_variance_identity} gives the upper bound. Hence
\begin{align*}
C(t;\kappa)\asymp\int_0^\tau v_\kappa(u)du
\refstepcounter{equation}\tag{\theequation}\label{C_variance_integral}
\end{align*}
for every $\beta_\rho\geq0$.

Applying \eqref{variance_integral_rates} with $p=2$ and $p=1$, and substituting $\beta_\rho=(\rho-1)/2$, gives
\begin{align*}
A(t;\kappa)&\asymp
\begin{cases}
\kappa^{-1},&1\leq\rho<5,\\
\frac{\ln(1+\kappa)}{\kappa},&\rho=5,\\
\kappa^{-4/(\rho-1)},&\rho>5,
\end{cases}\\
C(t;\kappa)&\asymp r_\rho(\kappa).
\refstepcounter{equation}\tag{\theequation}\label{coefficient_high_capacity_rates}
\end{align*}
In particular, $A(t;\kappa)$ is bounded above by a positive multiple of $r_\rho(\kappa)$ for all sufficiently large $\kappa$.

Finally, as $\mu$ ranges over $\mathbb{R}$, $z:=\left(\Delta^{NI}\right)^2$ ranges over $[0,\infty)$. By \eqref{correction_fluctuation_decomposition} and \eqref{p_sc_limit},
\begin{align*}
\sup_{\mu\in\mathbb{R}}
\frac{
P_{SC}^{AI,\infty}(\mu)-P_{SC}^{AI}(\mu,\kappa)
}{
P_{SC}^{AI,\infty}(\mu)-P_{SC}^{AI}(\mu,\bar\kappa)
}
&=
\sup_{z\geq0}
\frac{A(t;\kappa)z+C(t;\kappa)}
{A(t;\bar\kappa)z+C(t;\bar\kappa)}
=
\max\left\{
\frac{A(t;\kappa)}{A(t;\bar\kappa)},
\frac{C(t;\kappa)}{C(t;\bar\kappa)}
\right\}.
\end{align*}
Because $t<T$ and $\bar\kappa$ is finite, Theorem \ref{theorem_42} gives
\begin{align*}
A(t;\bar\kappa)>0,\qquad C(t;\bar\kappa)>0.
\end{align*}
Equation \eqref{coefficient_high_capacity_rates} implies that $C(t;\kappa)$ is bounded above and below by positive multiples of $r_\rho(\kappa)$, while $A(t;\kappa)$ is bounded above by a positive multiple of $r_\rho(\kappa)$. Dividing by the fixed positive benchmark coefficients and taking the maximum yields constants $0<K_1\leq K_2<\infty$ and $\kappa_0>\bar\kappa$ for which \eqref{voi_high_capacity_rates} holds.

Since $r_\rho(\kappa)\to0$, the upper bound in \eqref{voi_high_capacity_rates} is smaller than one for all sufficiently large $\kappa$. Hence,
\begin{align*}
P_{SC}^{AI,\infty}(\mu)-P_{SC}^{AI}(\mu,\kappa)
<
P_{SC}^{AI,\infty}(\mu)-P_{SC}^{AI}(\mu,\bar\kappa)
\end{align*}
uniformly in $\mu$, which proves \eqref{eventual_capacity_dominance}.
